                <a href="#" className="hover:opacity-70">Contact</a>
            </div>
            <a href="#" className="text-sm font-black border-b-2 border-current uppercase tracking-widest">Work with us</a>
        </div>
      </nav>

      <div ref={videoContainerRef} className="fixed inset-0 w-full h-full bg-black z-10 shadow-2xl pointer-events-none" style={{ clipPath: 'inset(100vh 50% 0 50%)' }}>
        <video className="w-full h-full object-cover" src="https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4" autoPlay muted loop playsInline />
      </div>

      <div ref={infoBarRef} className="fixed w-full z-30 flex justify-center opacity-0">
        <div className="flex flex-wrap items-center justify-center gap-8 px-4 font-heading font-bold italic tracking-tighter text-xl">
          <span>CAMPAIGNS</span><span>BRANDING</span><span>EVENT</span><span>DIGITAL</span>
