  const workTextRef = useRef<HTMLSpanElement>(null);
  const lastSectionRef = useRef<HTMLDivElement>(null);

  const currentScrollY = useRef(0);
  const [pageHeight, setPageHeight] = useState<number>(0);

  useEffect(() => {
    const calculateHeight = () => {
      if (lastSectionRef.current) {
        const startOffset = window.innerHeight * 4.2;
        const contentHeight = lastSectionRef.current.offsetHeight;
        setPageHeight(startOffset + contentHeight);
      }
    };
    calculateHeight();
    window.addEventListener('resize', calculateHeight);
    setTimeout(calculateHeight, 1000); // Wait for fonts/images
    return () => window.removeEventListener('resize', calculateHeight);
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const animate = () => {
      const targetScroll = window.scrollY;
      const windowHeight = window.innerHeight;
      const windowWidth = window.innerWidth;
      currentScrollY.current += (targetScroll - currentScrollY.current) * 0.12;

      if (contentRef.current) {
        contentRef.current.style.transform = `translate3d(0, -${currentScrollY.current}px, 0)`;
      }

      const animationRange = windowHeight * 2.5; 
      const scrollProgress = Math.max(0, Math.min(currentScrollY.current / animationRange, 1));

      if (videoContainerRef.current) {
        let widthEnd = 240, heightEnd = 120, topEnd = windowHeight - 240, leftEnd = (windowWidth - 240) / 2;

        if (finalPlaceholderRef.current) {
          const rect = finalPlaceholderRef.current.getBoundingClientRect();
          // Adjust for fixed container
          const scrollAdjust = currentScrollY.current;
          topEnd = rect.top + scrollAdjust; 
          leftEnd = rect.left;
          widthEnd = rect.width;
          heightEnd = rect.height;
        }

        const widthStart = 500, heightStart = 300, topStart = windowHeight * 1.0, leftStart = (windowWidth - 500) / 2;
        const widthMid = windowWidth, leftMid = 0, heightMid = windowHeight * 0.7, topMid = (windowHeight - (windowHeight * 0.7)) / 2;

        let currentTop, currentLeft, currentWidth, currentHeight;

        if (scrollProgress <= 0.5) {
          const p = scrollProgress * 2;
          const ease = p < 0.5 ? 2 * p * p : -1 + (4 - 2 * p) * p;
          currentTop = topStart + (topMid - topStart) * ease;
          currentLeft = leftStart + (leftMid - leftStart) * ease;
          currentWidth = widthStart + (widthMid - widthStart) * ease;
          currentHeight = heightStart + (heightMid - heightStart) * ease;
        } else {
          const p = (scrollProgress - 0.5) * 2;
          const ease = p < 0.5 ? 2 * p * p : -1 + (4 - 2 * p) * p;
          // Re-calculate rect because it might have moved or loaded
          if (finalPlaceholderRef.current) {
            const rect = finalPlaceholderRef.current.getBoundingClientRect();
            topEnd = rect.top + currentScrollY.current;
            leftEnd = rect.left;
            widthEnd = rect.width;
            heightEnd = rect.height;
          }
          currentTop = topMid + (topEnd - topMid) * ease;
          currentLeft = leftMid + (leftEnd - leftMid) * ease;
          currentWidth = widthMid + (widthEnd - widthMid) * ease;
          currentHeight = heightMid + (heightEnd - heightMid) * ease;
        }

        // Apply visual transform
        videoContainerRef.current.style.clipPath = `inset(${currentTop - currentScrollY.current}px ${windowWidth - (currentLeft + currentWidth)}px ${windowHeight - (currentTop - currentScrollY.current + currentHeight)}px ${currentLeft}px)`;

        if (infoBarRef.current) {
          let opacity = Math.max(0, Math.min(1 - Math.abs(scrollProgress - 0.5) * 6, 1));
          infoBarRef.current.style.opacity = opacity.toString();
          infoBarRef.current.style.transform = `translate3d(0, ${topMid + heightMid + 20 - currentScrollY.current}px, 0)`;
        }
      }

      if (workTextRef.current) {
        const startOffset = windowHeight * 4.2;
        const movement = Math.max(0, currentScrollY.current - startOffset) * 0.8;
        workTextRef.current.style.transform = `translate3d(0, ${movement}px, 0)`;
      }

      animationFrameId = requestAnimationFrame(animate);
    };
    animate();
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  return (
